Analyze and edit this Python code to make it faster def find_longest(arr):
    length = 0
    current_length = 0
    for i in range(len(arr) - 1):
        if arr[i] < arr[i+1]:
            current_length += 1
            if current_length > length:
                length = current_length
        else:
            current_length = 0
    return length

