Optimize this program in Python to find the highest peak in a given array def find_highest_peak(arr):
  highest_peak = 0
  for i in range(len(arr)):
    if i == 0:
      highest_peak = arr[i]
    else:
      if arr[i] > highest_peak:
        highest_peak = arr[i]  
  return highest_peak
